=====DISTANCE=====
"""净距规则族：要求两类对象之间保持最小边到边距离。

塔吊与基坑的净距、办公区与作业区的隔离都是本族的实例，只是措辞与严重程度不同；
用户注入的 min_distance 约束也在这里动态生成新实例，无需改动代码。
"""
from __future__ import annotations

from app.schemas.scene import Scene, SceneObject
from app.schemas.validation import Issue
from app.services.rules.base import DistanceRule, RuleContext
from app.services.rules.geometry import clear_distance


class PairDistanceRule(DistanceRule):
    """一对类型集合之间的最小净距判定。

    判定是对称的：无论候选对象落在配对的哪一侧，要求的净距都相同。
    """

    def __init__(self, code: str, primary_kinds: set[str], secondary_kinds: set[str],
                 distance: float, severity: str = "error", relaxable: bool = False) -> None:
        self.code = code
        self.primary_kinds = frozenset(primary_kinds)
        self.secondary_kinds = frozenset(secondary_kinds)
        self.distance = distance
        self.severity = severity
        self.relaxable = relaxable

    # -- 措辞：子类覆盖以给出更贴合该规则的表述 --------------------------------

    def _message(self, primary: SceneObject, secondary: SceneObject, gap: float) -> str:
        return f"{primary.name} 距 {secondary.name} {gap:.1f}m，小于 {self.distance:g}m。"

    def _suggestion(self, primary: SceneObject, secondary: SceneObject) -> str:
        return f"将 {primary.name} 移至距 {secondary.name} 不小于 {self.distance:g}m 处。"

    # -- 判定 ---------------------------------------------------------------

    def _applies(self, kind_a: str, kind_b: str) -> bool:
        return (
            (kind_a in self.primary_kinds and kind_b in self.secondary_kinds)
            or (kind_b in self.primary_kinds and kind_a in self.secondary_kinds)
        )

    def pair_gap(self, kind_a: str, kind_b: str) -> float | None:
        return self.distance if self._applies(kind_a, kind_b) else None

    def evaluate(self, scene: Scene, objects: list[SceneObject], ctx: RuleContext) -> list[Issue]:
        issues: list[Issue] = []
        for index, primary in enumerate(objects):
            if primary.kind not in self.primary_kinds:
                continue
            for offset, secondary in enumerate(objects):
                if secondary.kind not in self.secondary_kinds or secondary.id == primary.id:
                    continue
                # 两类集合相交时同一对会被正反遍历两次，只保留下标在前的一次。
                if primary.kind in self.secondary_kinds and secondary.kind in self.primary_kinds \
                        and offset < index:
                    continue
                gap = clear_distance(primary, secondary)
                if gap < self.distance:
                    issues.append(Issue(
                        code=self.code,
                        severity=self.severity,
                        message=self._message(primary, secondary, gap),
                        object_ids=[primary.id, secondary.id],
                        suggestion=self._suggestion(primary, secondary),
                    ))
        return issues

    def check_candidate(self, candidate: SceneObject, others: list[SceneObject],
                        scene: Scene, ctx: RuleContext) -> bool:
        # 候选类型与本规则无关时直接放行，不必扫描既有对象——螺旋搜索逐点调用，
        # 而场上多数对象与任一条净距规则都不相干。
        counterpart: set[str] = set()
        if candidate.kind in self.primary_kinds:
            counterpart |= self.secondary_kinds
        if candidate.kind in self.secondary_kinds:
            counterpart |= self.primary_kinds
        if not counterpart:
            return True
        for other in others:
            if other.kind not in counterpart:
                continue
            if clear_distance(candidate, other) < self.distance:
                return False
        return True


class CraneExcavationRule(PairDistanceRule):
    """塔吊与基坑的安全净距：基坑边坡影响塔吊基础，措辞按"距基坑边"表述。"""

    def _suggestion(self, primary: SceneObject, secondary: SceneObject) -> str:
        anchor = "基坑边" if secondary.kind == "excavation" else secondary.name
        return f"将 {primary.name} 移至距{anchor}不小于 {self.distance:g}m 处。"


class ZoneSeparationRule(PairDistanceRule):
    """生活办公与作业区的隔离：属建议性要求，措辞与严重程度都比硬性净距柔和。

    `relaxable` 为真——求解器在实在找不到位置时可放弃这条建议，
    先把对象落进场地，由校核以提醒的形式把隔离不足暴露给用户。
    """

    def _message(self, primary: SceneObject, secondary: SceneObject, gap: float) -> str:
        return f"{primary.name} 与 {secondary.name} 相距 {gap:.1f}m，建议不小于 {self.distance:g}m。"

    def _suggestion(self, primary: SceneObject, secondary: SceneObject) -> str:
        return f"建议将 {primary.name} 与 {secondary.name} 的间距拉开到 {self.distance:g}m 以上。"
=====OVERLAP=====
"""占地重叠：两个对象的足迹不得相交，豁免情形除外。

两类豁免（配置在 RuleContext，不散落在判定代码里）：

- 逐类豁免：消防通道、施工道路本就供其他对象穿越，与它们重叠不算问题；
- 逐对豁免：工程机械可以站在它正在作业的基坑里。
"""
from __future__ import annotations

from app.schemas.scene import Scene, SceneObject
from app.schemas.validation import Issue
from app.services.rules.base import Rule, RuleContext
from app.services.rules.geometry import footprint_corners, polygons_intersect


class OverlapRule(Rule):
    code = "OBJECT_OVERLAP"
    severity = "error"

    def _exempt(self, kind_a: str, kind_b: str, ctx: RuleContext) -> bool:
        if kind_a in ctx.overlap_exempt_kinds or kind_b in ctx.overlap_exempt_kinds:
            return True
        return frozenset({kind_a, kind_b}) in ctx.overlap_exempt_pairs

    def evaluate(self, scene: Scene, objects: list[SceneObject], ctx: RuleContext) -> list[Issue]:
        issues: list[Issue] = []
        for index, first in enumerate(objects):
            first_corners = footprint_corners(first)
            for second in objects[index + 1:]:
                if self._exempt(first.kind, second.kind, ctx):
                    continue
                if polygons_intersect(first_corners, footprint_corners(second)):
                    issues.append(Issue(
                        code=self.code,
                        severity=self.severity,
                        message=f"{first.name} 与 {second.name} 的占地范围重叠。",
                        object_ids=[first.id, second.id],
                        suggestion=f"移开 {first.name} 或 {second.name}，使两者占地不再重叠。",
                    ))
        return issues

    def check_candidate(self, candidate: SceneObject, others: list[SceneObject],
                        scene: Scene, ctx: RuleContext) -> bool:
        corners = footprint_corners(candidate)
        for other in others:
            if self._exempt(candidate.kind, other.kind, ctx):
                continue
            if polygons_intersect(corners, footprint_corners(other)):
                return False
        return True
=====BOUNDARY=====
"""红线越界：对象足迹必须完全落在场地范围内。"""
from __future__ import annotations

from app.schemas.scene import Scene, SceneObject
from app.schemas.validation import Issue
from app.services.rules.base import Rule, RuleContext
from app.services.rules.geometry import footprint_corners


class BoundaryRule(Rule):
    code = "OUT_OF_BOUNDARY"
    severity = "error"

    def _inside(self, obj: SceneObject, scene: Scene) -> bool:
        half_w, half_d = scene.site_width / 2, scene.site_depth / 2
        return not any(abs(x) > half_w or abs(z) > half_d for x, z in footprint_corners(obj))

    def evaluate(self, scene: Scene, objects: list[SceneObject], ctx: RuleContext) -> list[Issue]:
        return [
            Issue(
                code=self.code,
                severity=self.severity,
                message=f"{obj.name} 超出场地红线。",
                object_ids=[obj.id],
                suggestion=f"将 {obj.name} 移回红线范围内，或旋转后重新放置。",
            )
            for obj in objects
            if not self._inside(obj, scene)
        ]

    def check_candidate(self, candidate: SceneObject, others: list[SceneObject],
                        scene: Scene, ctx: RuleContext) -> bool:
        return self._inside(candidate, scene)
=====WIDTH=====
"""净宽规则：带状对象（消防通道等）的短边不得窄于要求值。

净宽取足迹短边而非固定某一维：对象可能被旋转 90° 使用，
按短边判定才与"通道有多宽"的现场语义一致。
"""
from __future__ import annotations

from app.schemas.scene import Scene, SceneObject
from app.schemas.validation import Issue
from app.services.rules.base import Rule, RuleContext


class MinWidthRule(Rule):
    code = "FIRE_LANE_WIDTH"
    severity = "error"
    # 净宽只取决于对象自身尺寸，与放在哪里无关，故不参与落位搜索（见 Rule.position_dependent）。
    position_dependent = False

    def __init__(self, kind: str, width: float, code: str | None = None,
                 severity: str = "error") -> None:
        self.kind = kind
        self.width = width
        if code is not None:
            self.code = code
        self.severity = severity

    def _too_narrow(self, obj: SceneObject) -> bool:
        return obj.kind == self.kind and min(obj.size.width, obj.size.depth) < self.width

    def evaluate(self, scene: Scene, objects: list[SceneObject], ctx: RuleContext) -> list[Issue]:
        return [
            Issue(
                code=self.code,
                severity=self.severity,
                message=f"{obj.name} 净宽小于 {self.width:g}m。",
                object_ids=[obj.id],
                suggestion=f"将 {obj.name} 的净宽调整到不小于 {self.width:g}m。",
            )
            for obj in objects
            if self._too_narrow(obj)
        ]

    def check_candidate(self, candidate: SceneObject, others: list[SceneObject],
                        scene: Scene, ctx: RuleContext) -> bool:
        return not self._too_narrow(candidate)
=====GEOMETRY=====
"""足迹几何：旋转矩形的角点、相交判定与边到边净距。

规则判定与布局求解共用这一份几何实现，任何一方都不得另写等价函数。
"""
from __future__ import annotations

import math

from app.schemas.scene import SceneObject


def footprint_corners(obj: SceneObject) -> list[tuple[float, float]]:
    """对象足迹绕自身中心旋转 rotation_y 后的四个角点。"""
    angle = math.radians(obj.rotation_y)
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    half_w, half_d = obj.size.width / 2, obj.size.depth / 2
    corners = []
    for dx, dz in ((-half_w, -half_d), (half_w, -half_d), (half_w, half_d), (-half_w, half_d)):
        corners.append((
            obj.position.x + dx * cos_a + dz * sin_a,
            obj.position.z - dx * sin_a + dz * cos_a,
        ))
    return corners


def polygons_intersect(a: list[tuple[float, float]], b: list[tuple[float, float]]) -> bool:
    """分离轴判定两个凸多边形是否相交：存在一条投影不重叠的轴即不相交。"""
    for polygon in (a, b):
        for index in range(len(polygon)):
            px, pz = polygon[index]
            qx, qz = polygon[(index + 1) % len(polygon)]
            axis = (qz - pz, -(qx - px))
            a_projection = [corner[0] * axis[0] + corner[1] * axis[1] for corner in a]
            b_projection = [corner[0] * axis[0] + corner[1] * axis[1] for corner in b]
            if max(a_projection) < min(b_projection) or max(b_projection) < min(a_projection):
                return False
    return True


def segment_distance(p1, p2, q1, q2) -> float:
    """两条线段之间的最短距离（四个端点到对侧线段的距离取最小）。"""
    def point_segment(point, a, b):
        ax, az = b[0] - a[0], b[1] - a[1]
        length_sq = ax * ax + az * az
        if length_sq == 0:
            return math.hypot(point[0] - a[0], point[1] - a[1])
        t = max(0.0, min(1.0, ((point[0] - a[0]) * ax + (point[1] - a[1]) * az) / length_sq))
        return math.hypot(point[0] - (a[0] + ax * t), point[1] - (a[1] + az * t))

    return min(
        point_segment(p1, q1, q2), point_segment(p2, q1, q2),
        point_segment(q1, p1, p2), point_segment(q2, p1, p2),
    )


def footprint_overlap(a: SceneObject, b: SceneObject) -> bool:
    return polygons_intersect(footprint_corners(a), footprint_corners(b))


def clear_distance(a: SceneObject, b: SceneObject) -> float:
    """两个旋转足迹的边到边净距；相交时为 0。

    取的是边到边而非中心距——现场说的"距基坑 3 米"指的是离基坑边缘，
    中心距会随对象尺寸漂移，与规范语义不符。
    """
    corners_a, corners_b = footprint_corners(a), footprint_corners(b)
    if polygons_intersect(corners_a, corners_b):
        return 0.0
    nearest = math.inf
    for i in range(len(corners_a)):
        for j in range(len(corners_b)):
            nearest = min(nearest, segment_distance(
                corners_a[i], corners_a[(i + 1) % len(corners_a)],
                corners_b[j], corners_b[(j + 1) % len(corners_b)],
            ))
    return nearest

import { computed, nextTick, ref } from 'vue'
import * as THREE from 'three/webgpu'
import { storeToRefs } from 'pinia'
import { useSceneStore } from '../store/useSceneStore'
import { useEarthworkStore } from '../store/useEarthworkStore'
import { useProjectStore } from '../store/useProjectStore'
import { useThreeScene } from './useThreeScene'
import { useTerrainEngine } from './useTerrainEngine'
import { makeLabel, useSceneObjects } from './useSceneObjects'
import { useCraneRig } from './useCraneRig'
import { useUndoStack } from './useUndoStack'
import { useValidation } from './useValidation'
import { postLayoutAssistStream } from '../api/client'
import type { Issue, SceneKind, Size, Vec2 } from '../types/scene'
import type { LayoutAssistResult } from '../types/api'

/**
 * AI 布置助手：SSE 流式对话、三维幽灵预览、方案应用与放弃。
 *
 * 对话为瞬态辅助，不随方案持久化；布置结果只有在用户点击"应用"后
 * 才写入 objects / earthworkOperations。预览体不进入拾取索引，
 * 因此不可点选、不影响既有交互。
 */

export interface AssistantMessage {
  role: 'user' | 'assistant'
  content: string
  thinking?: string
  status?: 'thinking' | 'done'
  issues?: Issue[]
}

interface GhostSource {
  name: string
  kind: string
  position: Vec2
  size: Size
  rotation_y?: number
}

const GHOST_HEIGHTS: Record<string, number> = { tower_crane: 14, excavation: 0.5, fence: 2.2, road: 0.2, fire_lane: 0.2 }

type LayoutAssistantApi = ReturnType<typeof createApi>
let api: LayoutAssistantApi | null = null

/** 由 App.vue 注入的资产库调色板：后端 SceneObject 不带颜色，应用时按 kind 派生。 */
let kindColors: Record<string, string> = {}

function createApi() {
  const sceneStore = useSceneStore()
  const earthworkStore = useEarthworkStore()
  const projectStore = useProjectStore()
  const { objects, selectedId, highlightedIds, activeMilestone, milestones } = storeToRefs(sceneStore)
  const { earthworkOperations } = storeToRefs(earthworkStore)
  const { markDirty } = projectStore
  const { ctx } = useThreeScene()
  const terrain = useTerrainEngine()
  const sceneObjects = useSceneObjects()
  const crane = useCraneRig()
  const { scenePayload, checkScene } = useValidation()
  const undoStack = useUndoStack()

  const assistantMessages = ref<AssistantMessage[]>([])
  const assistantInput = ref('')
  const assistantBusy = ref(false)
  const pendingProposal = ref<LayoutAssistResult | null>(null)
  const chatListEl = ref<HTMLElement | null>(null)
  let previewGroup: THREE.Group | null = null

  const proposalSummary = computed(() => {
    const proposal = pendingProposal.value
    if (!proposal) return ''
    const changes = proposal.actions.length + proposal.earthworks.length + (proposal.crane_actions?.length ?? 0)
    const errors = proposal.validation.issues.filter((issue) => issue.severity === 'error').length
    return `${changes} 项变更 · ${errors ? `${errors} 个校核错误` : '校核通过'}`
  })

  function setKindColors(colors: Record<string, string>) {
    kindColors = colors
  }

  function scrollChatToBottom() {
    nextTick(() => { if (chatListEl.value) chatListEl.value.scrollTop = chatListEl.value.scrollHeight })
  }

  function pushAssistantMessage(message: AssistantMessage) {
    assistantMessages.value.push(message)
    if (assistantMessages.value.length > 50) assistantMessages.value.splice(0, assistantMessages.value.length - 50)
    scrollChatToBottom()
  }

  async function sendAssistantMessage() {
    const text = assistantInput.value.trim()
    if (!text || assistantBusy.value) return
    if (pendingProposal.value) discardProposal(true)
    assistantInput.value = ''
    pushAssistantMessage({ role: 'user', content: text })
    const history = assistantMessages.value.slice(0, -1).slice(-8).map(({ role, content }) => ({ role, content }))
    assistantBusy.value = true
    // 占位消息从数组里取回代理对象再改字段，保证流式增量能触发响应式更新。
    pushAssistantMessage({ role: 'assistant', content: '', thinking: '', status: 'thinking' })
    const message = assistantMessages.value[assistantMessages.value.length - 1]
    try {
      // 网络层失败（后端没启动/断连）与服务返回错误分开提示，避免误导。
      const response = await postLayoutAssistStream({
        message: text,
        history,
        scene: scenePayload(),
        milestones: milestones.value.map((milestone, index) => ({ rank: index, name: milestone.name })),
      })
      if (!response) throw new Error('无法连接后端服务，请确认 FastAPI 已在 8000 端口启动。')
      if (!response.ok || !response.body) throw new Error(`布置服务异常（HTTP ${response.status}），请查看后端日志。`)
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      let result: LayoutAssistResult | null = null
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        let boundary
        while ((boundary = buffer.indexOf('\n\n')) >= 0) {
          const rawEvent = buffer.slice(0, boundary)
          buffer = buffer.slice(boundary + 2)
          let eventName = 'message'
          const dataLines: string[] = []
          for (const line of rawEvent.split('\n')) {
            if (line.startsWith('event:')) eventName = line.slice(6).trim()
            else if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart())
          }
          if (!dataLines.length) continue
          const data = JSON.parse(dataLines.join('\n'))
          if (eventName === 'thinking') {
            message.thinking = (message.thinking ?? '') + data
            scrollChatToBottom()
          } else if (eventName === 'result') {
            result = data
          }
        }
      }
      if (!result) throw new Error('布置服务响应不完整，请稍后重试。')
      message.status = 'done'
      message.content = result.reply
      message.issues = result.validation?.issues ?? []
      if (result.actions.length || result.earthworks.length || result.crane_actions?.length) {
        pendingProposal.value = result
        buildProposalPreview(result)
      }
    } catch (error) {
      message.status = 'done'
      message.content = (error as Error).message ?? '请求失败，请稍后重试。'
    } finally {
      assistantBusy.value = false
      scrollChatToBottom()
    }
  }

  // 幽灵体不走 makeObject（它会写 meshes/hitMeshes 并异步挂 GLTF），保持预览不可点选、不参与拾取。
  function makeGhost(object: GhostSource, color = '#38bdf8', opacity = 0.35) {
    const group = new THREE.Group()
    const height = GHOST_HEIGHTS[object.kind] ?? 2.4
    const geometry = new THREE.BoxGeometry(object.size.width, height, object.size.depth)
    const box = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite: false }))
    box.position.y = height / 2
    group.add(box)
    const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geometry), new THREE.LineBasicMaterial({ color }))
    edges.position.y = height / 2
    group.add(edges)
    const label = makeLabel(`${object.name}（预览）`)
    label.position.y = height + 1.4
    group.add(label)
    group.position.set(object.position.x, terrain.terrainHeightAt(object.position.x, object.position.z), object.position.z)
    group.rotation.y = THREE.MathUtils.degToRad(object.rotation_y ?? 0)
    return group
  }

  function buildProposalPreview(result: LayoutAssistResult) {
    clearProposalPreview(false)
    if (!ctx.scene) return
    previewGroup = new THREE.Group()
    previewGroup.name = 'ai-proposal-preview'
    const originIds: string[] = []
    result.actions.forEach((action) => {
      if (action.op === 'remove') {
        const target = objects.value.find((item) => item.id === action.object_id)
        if (target) {
          previewGroup!.add(makeGhost({ ...target, rotation_y: target.rotation ?? 0, name: `拟删除 ${target.name}` }, '#ef4444', 0.25))
          originIds.push(target.id)
        }
        return
      }
      if (!action.object) return
      previewGroup!.add(makeGhost(action.object))
      if (action.op === 'move' || action.op === 'modify') {
        const origin = objects.value.find((item) => item.id === action.object_id)
        if (origin) {
          originIds.push(origin.id)
          const from = new THREE.Vector3(origin.position.x, terrain.terrainHeightAt(origin.position.x, origin.position.z) + 1.2, origin.position.z)
          const to = new THREE.Vector3(action.object.position.x, terrain.terrainHeightAt(action.object.position.x, action.object.position.z) + 1.2, action.object.position.z)
          const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([from, to]), new THREE.LineDashedMaterial({ color: '#38bdf8', dashSize: 1, gapSize: 0.6 }))
          line.computeLineDistances()
          previewGroup!.add(line)
        }
      }
    })
    result.earthworks.forEach((earthwork) => {
      const draped = earthwork.polygon.map((point) => new THREE.Vector3(point.x, terrain.terrainHeightAt(point.x, point.z) + 0.18, point.z))
      if (draped.length > 1) {
        previewGroup!.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([...draped, draped[0].clone()]), new THREE.LineBasicMaterial({ color: '#c8894a' })))
      }
      if (draped.length > 2) {
        // Shape 平面经 rotateX(-π/2) 后 (x, y) → (x, 0, -y)，故 y 取 -z（与草图 overlay 同一约定）。
        const shape = new THREE.Shape(earthwork.polygon.map((point) => new THREE.Vector2(point.x, -point.z)))
        const fillGeometry = new THREE.ShapeGeometry(shape)
        fillGeometry.rotateX(-Math.PI / 2)
        const fillMesh = new THREE.Mesh(fillGeometry, new THREE.MeshBasicMaterial({ color: '#c8894a', transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false }))
        fillMesh.position.y = Math.max(...draped.map((point) => point.y)) + 0.1
        previewGroup!.add(fillMesh)
      }
    })
    ctx.scene.add(previewGroup)
    if (originIds.length) {
      // 预览高亮不自动消退，跟随预览生命周期由 clearProposalPreview 清除。
      sceneObjects.setHighlight(originIds)
      sceneObjects.rebuildAll()
    }
  }

  function clearProposalPreview(rebuild = true) {
    if (previewGroup) {
      ctx.scene?.remove(previewGroup)
      previewGroup.traverse((child) => {
        const mesh = child as THREE.Mesh
        // Sprite 的 geometry 是 three 的**模块级共享单例**（Sprite.js 的 `_geometry`，
        // 全场景所有 Sprite 共用同一份），dispose 它会连带销毁其他标签仍在用的 GPU buffer：
        // WebGPU 下表现为此后每帧一条 GPUValidationError "used in submit while destroyed"
        // （WebGL 后端不校验此项，故迁移前不显形）。标签的私有资源只有贴图与材质，逐个释放即可。
        if (!(child as THREE.Sprite).isSprite) mesh.geometry?.dispose?.()
        const material = mesh.material as (THREE.Material & { map?: THREE.Texture }) | undefined
        if (material?.map) material.map.dispose()
        material?.dispose?.()
      })
      previewGroup = null
    }
    if (highlightedIds.value.length) {
      highlightedIds.value = []
      if (rebuild) sceneObjects.rebuildAll()
    }
  }

  function applyProposal() {
    const proposal = pendingProposal.value
    if (!proposal) return
    // 整份方案记一步撤销（§5.5 的对象增删改）：AI 一次落位往往同时增删改多个对象，
    // 用户要的是"这次 AI 布置不算数"，而不是逐个对象往回退。
    // 方案内附带的土方操作不随撤销回退（土方不入栈），撤销后需在操作清单里另行处理。
    undoStack.pushStep(`应用 AI 布置（${proposal.actions.length} 项）`)
    // 后端 phase 是 rank（数组下标）；阶段可重排，必须经 milestones 数组还原为稳定 id。
    const rankToId = (rank?: number): string =>
      milestones.value[Math.min(Math.max(rank ?? 0, 0), milestones.value.length - 1)]?.id ?? activeMilestone.value
    proposal.actions.forEach((action) => {
      if (action.op === 'remove') {
        objects.value = objects.value.filter((item) => item.id !== action.object_id)
        if (selectedId.value === action.object_id) selectedId.value = null
        return
      }
      if (!action.object) return
      const solved = action.object
      const index = objects.value.findIndex((item) => item.id === action.object_id)
      if (index >= 0) {
        objects.value[index] = {
          ...objects.value[index],
          name: solved.name,
          position: { x: solved.position.x, z: solved.position.z },
          size: { width: solved.size.width, depth: solved.size.depth },
          rotation: solved.rotation_y ?? 0,
          phase: rankToId(solved.phase),
        }
      } else {
        objects.value.push({
          id: solved.id,
          name: solved.name,
          kind: solved.kind as SceneKind,
          position: { x: solved.position.x, z: solved.position.z },
          size: { width: solved.size.width, depth: solved.size.depth },
          color: kindColors[solved.kind] ?? '#94a3b8',
          movable: solved.movable ?? true,
          rotation: solved.rotation_y ?? 0,
          phase: rankToId(solved.phase),
        })
      }
    })
    proposal.earthworks.forEach((earthwork) => {
      const milestoneId = rankToId(earthwork.milestone_rank)
      const baseline = earthwork.polygon.reduce((sum, point) => sum + terrain.terrainHeightAt(point.x, point.z), 0) / Math.max(earthwork.polygon.length, 1)
      const magnitude = Number(earthwork.depth)
      earthworkOperations.value.push({
        id: earthwork.id,
        name: earthwork.name,
        type: earthwork.type,
        enabled: true,
        polygon: earthwork.polygon.map((point) => ({ x: point.x, z: point.z })),
        baseElevation: Number(baseline.toFixed(2)),
        targetElevation: Number((baseline + (earthwork.type === 'fill' ? magnitude : -magnitude)).toFixed(2)),
        depth: magnitude,
        width: 4,
        slopeRatio: earthwork.slope_ratio ?? 0.5,
        milestone: milestoneId,
        sequence: earthworkOperations.value.filter((item) => item.milestone === milestoneId).length + 1,
        quantities: { cut: 0, fill: 0, net: 0 },
        // 模型只输出深度意图、不感知参考面：挖至面须由用户在操作参数中显式改挂。
        targetMode: 'depth',
      })
    })
    const hadEarthworks = proposal.earthworks.length > 0
    pendingProposal.value = null
    clearProposalPreview(false)
    sceneObjects.rebuildAll()
    if (hadEarthworks) terrain.replayEarthwork()
    // 塔吊动作在重建后入队；模型异步加载完成前先暂存，加载完自动执行。
    if (proposal.crane_actions?.length) crane.queueCraneActions(proposal.crane_actions)
    checkScene()
    markDirty()
    pushAssistantMessage({ role: 'assistant', content: '已应用布置方案，可继续用对话调整，或在场景中直接拖拽微调。' })
  }

  function discardProposal(silent = false) {
    pendingProposal.value = null
    clearProposalPreview()
    if (!silent) pushAssistantMessage({ role: 'assistant', content: '已放弃该布置方案，场景未做任何修改。' })
  }

  return {
    assistantMessages, assistantInput, assistantBusy, pendingProposal, chatListEl, proposalSummary,
    setKindColors,
    sendAssistantMessage, applyProposal, discardProposal, clearProposalPreview,
  }
}

/** 单例访问器（须在 Pinia 激活后首次调用）。 */
export function useLayoutAssistant() {
  if (!api) api = createApi()
  return api
}
=====CLIENT=====
/**
 * 后端 /api/* 调用的集中封装。
 *
 * 错误语义约定：各函数在服务返回非 2xx 时抛出与原实现完全一致的中文/英文
 * 错误消息（调用方直接把 error.message 展示给用户），因此禁止改写这些文案。
 * 布置助手为 SSE 流式接口，此处只负责发起请求；网络层失败返回 null 交由
 * 调用方与"服务返回错误"区分提示。
 */
import type {
  ConstraintResult,
  LayoutAssistResult,
  LayoutAssistStreamBody,
  ScenePayload,
  TerrainImageryParams,
  TerrainVolumeRequest,
  TerrainVolumeResult,
  ValidationResult,
} from '../types/api'

function postJson(url: string, body: unknown): Promise<Response> {
  return fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
}

export async function postValidate(payload: ScenePayload): Promise<ValidationResult> {
  const response = await postJson('/api/validate', payload)
  if (!response.ok) throw new Error('校核服务不可用')
  return response.json()
}

export async function postInterpretConstraints(text: string): Promise<ConstraintResult> {
  const response = await postJson('/api/constraints/interpret', { text })
  if (!response.ok) throw new Error('规范解析服务不可用')
  return response.json()
}

export async function postTerrainVolume(body: TerrainVolumeRequest): Promise<TerrainVolumeResult> {
  const response = await postJson('/api/terrain/volume', body)
  if (!response.ok) throw new Error('volume service unavailable')
  return response.json()
}

/** 拉取项目范围的卫星影像拼图；返回图片 Blob，内容非图片或过小时视为失败。 */
export async function fetchTerrainImagery(params: TerrainImageryParams): Promise<Blob> {
  const response = await postJson('/api/terrain/imagery', params)
  if (!response.ok) throw new Error(`影像服务响应 ${response.status}`)
  const blob = await response.blob()
  if (!blob.type.startsWith('image/') || blob.size < 1024) throw new Error('影像服务未返回有效图片')
  return blob
}

/**
 * 发起布置助手流式请求。网络层失败（后端未启动/断连）返回 null，
 * 由调用方给出连接类提示；HTTP 错误保留在 Response 上由调用方判断。
 */
export function postLayoutAssistStream(body: LayoutAssistStreamBody): Promise<Response | null> {
  return postJson('/api/layout/assist/stream', body).catch(() => null)
}

export type { LayoutAssistResult }
=====API_TYPES=====
/**
 * 后端 /api/* 接口的请求与响应类型。
 *
 * 与 `backend/app/schemas/` 保持字段一致：后端对象使用 `rotation_y`（度）与
 * `phase`（阶段 rank，即数组下标），前端应用结果时需转换回本地的
 * `rotation` / 阶段稳定 id，转换逻辑见 App.vue 的 applyProposal。
 */
import type { Constraint, Issue, SceneKind, Size, Vec2 } from './scene'

/** 提交校核/布置时的对象快照（scenePayload 的元素）。 */
export interface ScenePayloadObject {
  id: string
  name: string
  kind: SceneKind
  position: Vec2
  size: Size
  rotation_y: number
  movable: boolean
  /** 出现阶段 rank（数组下标）。 */
  phase: number
  /** 消失阶段 rank；null 表示存在至时间轴终点，与后端 `phase_end` 默认值一致。 */
  phase_end: number | null
}

export interface ScenePayload {
  site_width: number
  site_depth: number
  active_milestone: number
  constraints: Constraint[]
  objects: ScenePayloadObject[]
}

export interface ValidationResult {
  valid: boolean
  issues: Issue[]
  notes?: string[]
}

export interface ConstraintResult {
  constraints: Constraint[]
  note: string
}

export interface TerrainVolumeRequest {
  original_heights: number[]
  current_heights: number[]
  cell_area_m2: number
}

export interface TerrainVolumeResult {
  cut: number
  fill: number
  net: number
}

export interface TerrainImageryParams {
  west: number
  east: number
  south: number
  north: number
  zoom: number
}

/** 后端求解后的场景对象（含坐标）。kind 由后端 SceneKind 枚举保证取值合法。 */
export interface SolvedObject {
  id: string
  name: string
  kind: SceneKind
  position: Vec2
  size: Size
  rotation_y?: number
  movable?: boolean
  /** 阶段 rank（数组下标），非稳定 id。 */
  phase?: number
}

export interface SolvedAction {
  op: 'add' | 'move' | 'remove' | 'modify'
  object_id: string
  object?: SolvedObject | null
  note?: string
}

export interface SolvedEarthwork {
  id: string
  name: string
  type: 'cut' | 'fill'
  polygon: Vec2[]
  depth: number
  slope_ratio?: number
  milestone_rank?: number
  linked_object_id?: string | null
}

export interface SolvedCraneAction {
  object_id: string
  name?: string
  slew_deg?: number | null
  slew_delta_deg?: number | null
  trolley_radius_m?: number | null
  hook?: 'ground' | 'up' | null
  hook_drop_m?: number | null
  note?: string
}

export interface LayoutAssistResult {
  reply: string
  actions: SolvedAction[]
  earthworks: SolvedEarthwork[]
  crane_actions?: SolvedCraneAction[]
  validation: ValidationResult
  intent_source?: 'model' | 'rules'
  notes?: string[]
}

export interface LayoutAssistStreamBody {
  message: string
  history: { role: string; content: string }[]
  scene: ScenePayload
  milestones: { rank: number; name: string }[]
}

