/**
 * 整场布置：一段施工组织要求一次生成完整方案。
 *
 * 非流式——整场求解是后端确定性计算，没有逐字产出的思维链可推送，
 * 等一次完整响应比假装流式更贴合实际。
 */
export async function postSitePlan(body: SitePlanBody): Promise<SitePlanResult> {
  const response = await postJson('/api/layout/site-plan', body)
  if (!response.ok) throw new Error(`整场布置服务异常（HTTP ${response.status}），请查看后端日志。`)
  return response.json()
}

