   * 整场布置：一段施工组织要求 → 后端一次求解出完整方案 → 走同一条预览通道。
   *
   * 非流式：整场求解是后端确定性计算，没有逐字产出的思维链可推送。
   * 返回结构是 LayoutAssistResult 的超集，因此可直接赋给 pendingProposal，
   * 后续的预览、应用、放弃完全复用既有实现。
   */
  async function sendSitePlanRequest() {
    const text = assistantInput.value.trim()
    if (!text || assistantBusy.value) return
    if (pendingProposal.value) discardProposal(true)
    assistantInput.value = ''
    pushAssistantMessage({ role: 'user', content: text })
    const history = assistantMessages.value.slice(0, -1).slice(-8).map(({ role, content }) => ({ role, content }))
    assistantBusy.value = true
    pushAssistantMessage({ role: 'assistant', content: '', status: 'thinking' })
    const message = assistantMessages.value[assistantMessages.value.length - 1]
    try {
      const result = await postSitePlan({
        message: text,
        history,
        scene: scenePayload(),
        milestones: milestones.value.map((milestone, index) => ({ rank: index, name: milestone.name })),
        variants: compareVariants.value ? 2 : 1,
      })
      message.status = 'done'
      message.content = result.reply
      message.issues = result.validation?.issues ?? []
      message.score = {
        total: result.total_penalty,
        top: topPenalties(result.scores),
        unplaced: result.unplaced ?? [],
      }
      sitePlanResult.value = result
      if (result.actions.length || result.earthworks.length) {
        pendingProposal.value = result
        buildProposalPreview(result)
      }
    } catch (error) {
      message.status = 'done'
      message.content = (error as Error).message ?? '整场布置请求失败，请稍后重试。'
    } finally {
      assistantBusy.value = false
      scrollChatToBottom()
    }
  }

  /** 全场扣分最高的前若干项，供评分卡展示（后端已按对象内降序，这里跨对象再排一次）。 */
  function topPenalties(scores: SitePlanResult['scores'], limit = 3): PenaltyItem[] {
    return scores
      .flatMap((score) => score.breakdown)
      .sort((left, right) => right.penalty - left.penalty)
      .slice(0, limit)
  }

  async function sendAssistantMessage() {
    if (sitePlanMode.value) return sendSitePlanRequest()
    const text = assistantInput.value.trim()
    if (!text || assistantBusy.value) return
    if (pendingProposal.value) discardProposal(true)
    assistantInput.value = ''"}

